-- Optional cleanup for the "Unit Unit A" display bug (part of the
-- "Product and legal messaging needing review" audit items): every
-- display site already prepends "Unit " in front of unit_number, so a
-- unit_number that itself starts with "Unit " (auto-generated by the
-- old property-creation code, or typed by a landlord following the old
-- "Unit 3" placeholder) doubles up. The app-side fix stops NEW units
-- from being created this way; this corrects units that already exist.
--
-- Only strips a leading "Unit" (case-insensitive, optional separator) —
-- never touches a unit_number that doesn't start with it, so "Main",
-- "2B", "A", etc. are left alone.
update public.units
set unit_number = trim(regexp_replace(unit_number, '^\s*unit\.?\s*#?\s*', '', 'i'))
where unit_number ~* '^\s*unit\.?\s*#?\s*\S';
